#!/usr/bin/env python3
"""
patch_finance_app_s218.py -- S218 final-run server side, ONE anchored change:
replaces the S217 statement-health route (exact bytes asserted) with the v2
block that also carries /finance/api/walk, /mpr-day, /review-list, /heal-now
and /cards. English strings throughout (owner ruling 02-Sep). All new routes
are READ-ONLY except heal-now, which runs finance_heal (its own module).
SAFETY: exact-once assert, timestamped backup, compile-with-restore.
USAGE: /root/wa/venv/bin/python3 -B /root/finance/patch_finance_app_s218.py
"""
import datetime as dt
import os
import shutil
import sys

TARGET = os.environ.get("FA_PATH", "/root/finance/finance_app.py")
MARK = "S218 v2 (statement health)"

OLD = '@app.route("/finance/api/statement-health", methods=["GET"])\ndef api_statement_health():\n    """S217 (statement health) -- the owner\'s words: "make it impossible for\n    me to miss it on my page." The server composes the sentences; the pages\n    only display them (D349: one copy of every rule). READ-ONLY."""\n    u, err = require("maker", "checker")\n    if err:\n        return err\n    import datetime as _dt                                   # noqa: PLC0415\n    con = db()\n    today = _dt.date.today()\n    cutoff = (today - _dt.timedelta(days=9)).isoformat()\n    days = {}\n    for r in con.execute(\n            "SELECT business_date, status, entered_by, entered_at, "\n            " approved_by, approved_at FROM day_entry "\n            "WHERE unit=? AND business_date>=?", (UNIT, cutoff)):\n        days[r["business_date"]] = dict(r)\n    stmts = {}\n    for r in con.execute(\n            "SELECT statement_date, parsed_total_p FROM upi_statement "\n            "WHERE unit=? AND statement_date>=?", (UNIT, cutoff)):\n        stmts[r["statement_date"]] = r["parsed_total_p"]\n    dz = con.execute("SELECT MAX(visit_date) m FROM patient_visit").fetchone()\n    docterz_last = dz["m"] if dz and dz["m"] else None\n    att, dpend, out_days = [], [], []\n    latest = None\n    drawer_inflated = False\n    for i in range(9, -1, -1):\n        d = today - _dt.timedelta(days=i)\n        iso = d.isoformat()\n        sunday = d.weekday() == 6\n        e = days.get(iso)\n        st_present = iso in stmts\n        row = dict(date=iso, sunday=sunday,\n                   status=(e["status"] if e else None),\n                   entered_by=(e["entered_by"] if e else None),\n                   entered_at=(e["entered_at"] if e else None),\n                   approved_by=(e["approved_by"] if e else None),\n                   approved_at=(e["approved_at"] if e else None),\n                   statement=("present" if st_present\n                              else ("not_expected" if sunday else "missing")),\n                   bank_p=stmts.get(iso))\n        out_days.append(row)\n        if e:\n            latest = row\n        if iso == today.isoformat():\n            continue        # today is not yet due -- neither filing nor bank\n        if not e and not sunday:\n            att.append(dict(cls="bad",\n                text=u"\\\\u26a0 %s abhi FILE nahin hua \\\\u2014 din ka form pending hai." % iso,\n                sub="No day entry exists for this date. Nothing reconciles "\n                    "until it is filed."))\n        if e and not st_present and not sunday:\n            att.append(dict(cls="warn",\n                text=u"\\\\u26a0 Bank UPI statement for %s has NOT arrived \\\\u2014 "\n                     u"drawer will read INFLATED until it lands." % iso,\n                sub="ICICI\'s mail lands ~11am and is pushed hourly; when it "\n                    "arrives, any UPI typed as cash flags on its own."))\n            drawer_inflated = True\n        if e and docterz_last and iso > docterz_last:\n            dpend.append(iso)\n    if dpend:\n        att.append(dict(cls="info",\n            text=u"\\\\u24d8 Docterz report upload pending for: %s" % ", ".join(dpend),\n            sub="Export the day report from Docterz on the clinic PC; the "\n                "tracker push re-matches the waiting bills automatically."))\n    return jsonify(ok=True, unit=UNIT, today=today.isoformat(),\n                   days=out_days, latest_filed=latest, attention=att,\n                   docterz_last=docterz_last, docterz_pending=dpend,\n                   drawer_inflated=drawer_inflated)\n\n\n'

NEW = '@app.route("/finance/api/statement-health", methods=["GET"])\ndef api_statement_health():\n    """S218 v2 (statement health) -- English only (owner ruling 02-Sep); adds\n    open-exception / flag / review counts and the positive Docterz line.\n    The server composes the sentences; pages only display (D349). READ-ONLY."""\n    u, err = require("maker", "checker")\n    if err:\n        return err\n    import datetime as _dt                                   # noqa: PLC0415\n    con = db()\n    today = _dt.date.today()\n    cutoff = (today - _dt.timedelta(days=9)).isoformat()\n    days = {}\n    for r in con.execute(\n            "SELECT business_date, status, entered_by, entered_at, "\n            " approved_by, approved_at FROM day_entry "\n            "WHERE unit=? AND business_date>=?", (UNIT, cutoff)):\n        days[r["business_date"]] = dict(r)\n    stmts = {}\n    for r in con.execute(\n            "SELECT statement_date, parsed_total_p FROM upi_statement "\n            "WHERE unit=? AND statement_date>=?", (UNIT, cutoff)):\n        stmts[r["statement_date"]] = r["parsed_total_p"]\n    dz = con.execute("SELECT MAX(visit_date) m FROM patient_visit").fetchone()\n    docterz_last = dz["m"] if dz and dz["m"] else None\n    att, dpend, out_days = [], [], []\n    latest = None\n    drawer_inflated = False\n    for i in range(9, -1, -1):\n        d = today - _dt.timedelta(days=i)\n        iso = d.isoformat()\n        sunday = d.weekday() == 6\n        e = days.get(iso)\n        st_present = iso in stmts\n        row = dict(date=iso, sunday=sunday,\n                   status=(e["status"] if e else None),\n                   entered_by=(e["entered_by"] if e else None),\n                   entered_at=(e["entered_at"] if e else None),\n                   approved_by=(e["approved_by"] if e else None),\n                   approved_at=(e["approved_at"] if e else None),\n                   statement=("present" if st_present\n                              else ("not_expected" if sunday else "missing")),\n                   bank_p=stmts.get(iso))\n        out_days.append(row)\n        if e:\n            latest = row\n        if iso == today.isoformat():\n            continue\n        if not e and not sunday:\n            att.append(dict(cls="bad",\n                text=u"⚠ %s is NOT FILED yet." % iso,\n                sub="No day entry exists. Nothing reconciles until it is filed."))\n        if e and not st_present and not sunday:\n            att.append(dict(cls="warn",\n                text=u"⚠ Bank UPI statement for %s has NOT arrived - "\n                     u"the drawer will read INFLATED until it lands." % iso,\n                sub="Pushed hourly; when it arrives, any UPI typed as cash "\n                    "flags on its own."))\n            drawer_inflated = True\n        if e and docterz_last and iso > docterz_last:\n            dpend.append(iso)\n    if dpend:\n        att.append(dict(cls="info",\n            text=u"ⓘ Docterz visits pending for: %s" % ", ".join(dpend),\n            sub="Two legs: export the day report from Docterz, then the "\n                "tracker push (PUSH_TODAY.bat runs both since 02-Sep). The "\n                "VPS applies hourly at :20."))\n    elif docterz_last:\n        att.append(dict(cls="ok",\n            text=u"✓ Docterz visits current through %s." % docterz_last))\n    exc = con.execute("SELECT COUNT(*) c FROM recon_exception WHERE status=\'open\'").fetchone()["c"]\n    flg = con.execute("SELECT COUNT(*) c FROM data_flag WHERE business_date>=?",\n                      (cutoff,)).fetchone()["c"]\n    rev = con.execute("SELECT COUNT(*) c FROM sale_item_review WHERE status=\'open\'").fetchone()["c"]\n    if exc or flg:\n        att.append(dict(cls="warn",\n            text=u"⚠ %d open exception(s) · %d flag(s) in the last 10 days."\n                 % (exc, flg),\n            sub="The Walk covers each one; Recheck heals what the feeds have "\n                "since answered."))\n    if rev:\n        att.append(dict(cls="info",\n            text=u"ⓘ Review queue: %d open row(s)." % rev,\n            sub="Mostly parked credit notes and low-confidence bills; the "\n                "returns build clears them by lookup."))\n    return jsonify(ok=True, unit=UNIT, today=today.isoformat(),\n                   days=out_days, latest_filed=latest, attention=att,\n                   docterz_last=docterz_last, docterz_pending=dpend,\n                   drawer_inflated=drawer_inflated,\n                   open_exceptions=exc, flags_recent=flg, review_open=rev)\n\n\n@app.route("/finance/api/walk", methods=["GET"])\ndef api_walk():\n    """S218 -- the Walk: one severity-ordered queue, composed here so no rule\n    lives twice. Steps carry act-in-place hints; the page renders. READ-ONLY\n    (the heal pass is separate, at /finance/api/heal-now)."""\n    u, err = require("checker")\n    if err:\n        return err\n    import datetime as _dt                                   # noqa: PLC0415\n    con = db()\n    today = _dt.date.today()\n    steps = []\n    for i in range(9, 0, -1):\n        d = today - _dt.timedelta(days=i)\n        if d.weekday() == 6:\n            continue\n        iso = d.isoformat()\n        if not con.execute("SELECT 1 FROM day_entry WHERE unit=? AND business_date=?",\n                           (UNIT, iso)).fetchone():\n            steps.append(dict(sev="bad", kind="not_filed", day=iso,\n                title="%s is not filed" % iso,\n                body="No day entry exists; nothing reconciles until it is filed.",\n                links=[dict(label="open the maker page", url="/finance/daily?d=" + iso)]))\n    for r in con.execute("SELECT business_date d, status FROM day_entry "\n                         "WHERE unit=? AND status IN (\'submitted\',\'draft\') "\n                         "ORDER BY business_date", (UNIT,)):\n        steps.append(dict(sev="bad", kind="awaiting_approval", day=r["d"],\n            title="%s awaits your approval" % r["d"],\n            body="Status: %s. Approve right here." % r["status"],\n            approve_date=r["d"]))\n    for r in con.execute("SELECT id, business_date d, expected_p, actual_p, diff_p "\n                         "FROM recon_exception WHERE unit=? AND status=\'open\' "\n                         "AND kind=\'upi_vs_statement\' ORDER BY business_date", (UNIT,)):\n        tot = con.execute("SELECT COALESCE(SUM(amount_p),0) p FROM day_line l "\n                          "JOIN day_entry e ON e.id=l.day_entry_id WHERE e.unit=? "\n                          "AND e.business_date=? AND l.mode IN (\'cash\',\'upi\')",\n                          (UNIT, r["d"])).fetchone()["p"]\n        bank = int(r["expected_p"] or 0)\n        steps.append(dict(sev="bad", kind="upi_vs_statement", day=r["d"], id=r["id"],\n            title="%s - bank vs entered" % r["d"],\n            body=("Rs %.2f arrived by UPI but Rs %.2f was entered - the money "\n                  "reached the bank; the books\' drawer reads too high by Rs %.2f. "\n                  "Nobody owes cash; the day\'s modes need correcting. "\n                  "Corrected split: cash %.2f, UPI %.2f."\n                  % (bank / 100.0, (r["actual_p"] or 0) / 100.0,\n                     abs(r["diff_p"] or 0) / 100.0,\n                     max(tot - bank, 0) / 100.0, bank / 100.0)),\n            links=[dict(label="open the day", url="/finance/daily?d=" + r["d"]),\n                   dict(label="Amir\'s corrections desk", url="/finance/darpan/corrections")]))\n    for r in con.execute("SELECT id, business_date d, kind, diff_p, detail "\n                         "FROM recon_exception WHERE unit=? AND status=\'open\' "\n                         "AND kind NOT IN (\'upi_vs_statement\',\'clinic_holiday\') "\n                         "ORDER BY business_date", (UNIT,)):\n        steps.append(dict(sev="warn", kind=r["kind"], day=r["d"], id=r["id"],\n            title="%s - %s" % (r["d"], r["kind"].replace("_", " ")),\n            body=(r["detail"] or "")[:240], resolve_id=r["id"]))\n    cutoff = (today - _dt.timedelta(days=10)).isoformat()\n    for r in con.execute("SELECT business_date d, code, COUNT(*) n, MAX(detail) detail "\n                         "FROM data_flag WHERE business_date>=? "\n                         "GROUP BY business_date, code ORDER BY business_date", (cutoff,)):\n        steps.append(dict(sev="warn", kind="flag", day=r["d"],\n            title="%s - flag %s%s" % (r["d"] or "", r["code"],\n                                      (" x%d" % r["n"]) if r["n"] > 1 else ""),\n            body=(r["detail"] or "")[:240], heal=True))\n    rev = con.execute("SELECT COUNT(*) c FROM sale_item_review WHERE status=\'open\'").fetchone()["c"]\n    if rev:\n        steps.append(dict(sev="info", kind="review", title="Review queue: %d open" % rev,\n            body="Mostly parked credit notes and low-confidence bills; the "\n                 "returns build clears them by lookup. Browse them on the card.",\n            goto="reviewCard"))\n    order = {"bad": 0, "warn": 1, "info": 2}\n    steps.sort(key=lambda s: order.get(s["sev"], 3))\n    return jsonify(ok=True, steps=steps, count=len(steps))\n\n\n@app.route("/finance/api/mpr-day", methods=["GET"])\ndef api_mpr_day():\n    """S218 -- the bank\'s own MPR detail for one day, all units; expandable on\n    the owner\'s card, exportable for Darpan/Amir. READ-ONLY."""\n    u, err = require("maker", "checker")\n    if err:\n        return err\n    d = (request.args.get("d") or "").strip()\n    if not d:\n        import datetime as _dt                               # noqa: PLC0415\n        d = (_dt.date.today() - _dt.timedelta(days=1)).isoformat()\n    con = db()\n    units = {}\n    for r in con.execute("SELECT unit, rrn, mode, txn_time, amount_p FROM upi_txn "\n                         "WHERE txn_date=? ORDER BY unit, txn_time", (d,)):\n        units.setdefault(r["unit"], []).append(\n            dict(rrn=r["rrn"], mode=r["mode"], time=r["txn_time"], amount_p=r["amount_p"]))\n    tot = {}\n    for r in con.execute("SELECT unit, parsed_total_p, txn_count FROM upi_statement "\n                         "WHERE statement_date=?", (d,)):\n        tot[r["unit"]] = dict(total_p=r["parsed_total_p"], txns=r["txn_count"])\n    return jsonify(ok=True, date=d, units=units, totals=tot)\n\n\n@app.route("/finance/api/review-list", methods=["GET"])\ndef api_review_list():\n    """S218 -- the open review rows, visible and countable. Clearing lands\n    with the returns build. READ-ONLY."""\n    u, err = require("checker")\n    if err:\n        return err\n    con = db()\n    rows = []\n    for r in con.execute(\n            "SELECT r.id, d.business_date bd, r.guess_clinic_id, r.guess_name, "\n            "r.amount_p, r.confidence, r.reason FROM sale_item_review r "\n            "JOIN day_entry d ON d.id=r.day_entry_id WHERE r.status=\'open\' "\n            "ORDER BY d.business_date DESC LIMIT 300"):\n        rows.append(dict(id=r["id"], date=r["bd"], name=r["guess_name"],\n                         clinic_id=r["guess_clinic_id"], amount_p=r["amount_p"],\n                         confidence=r["confidence"], reason=r["reason"]))\n    return jsonify(ok=True, rows=rows, count=len(rows))\n\n\n@app.route("/finance/api/heal-now", methods=["POST"])\ndef api_heal_now():\n    """S218 -- the Recheck button: run the heal pass now."""\n    u, err = require("checker")\n    if err:\n        return err\n    try:\n        import finance_heal                                  # noqa: PLC0415\n    except ImportError:\n        return jsonify(ok=False, error="module_absent",\n                       message="finance_heal.py is not in /root/finance/"), 503\n    out = finance_heal.run(db())\n    return jsonify(ok=True, **out)\n\n\n@app.route("/finance/api/cards", methods=["GET"])\ndef api_cards():\n    """S218 -- the staff cards registry; /finance/darpan renders it. A new\n    card ships with its registry row; no hand-edited list."""\n    u, err = require("maker", "checker")\n    if err:\n        return err\n    import json as _json                                     # noqa: PLC0415\n    import os as _os                                         # noqa: PLC0415\n    p = _os.path.join(_os.path.dirname(_os.path.abspath(DB_PATH)),\n                      "cards_registry.json")\n    try:\n        with open(p, encoding="utf-8") as fh:\n            data = _json.load(fh)\n    except OSError:\n        return jsonify(ok=False, error="registry_missing"), 503\n    return jsonify(ok=True, cards=data.get("cards", []))\n\n\n'


def main():
    src = open(TARGET, encoding="utf-8").read()
    if MARK in src:
        print("already patched (%s) -- nothing to do" % MARK)
        return 0
    n = src.count(OLD)
    if n != 1:
        raise SystemExit("REFUSED: v1 statement-health matches %d times (need 1)." % n)
    stamp = dt.datetime.now().strftime("%Y%m%d-%H%M%S")
    bak = TARGET + ".bak_S218_" + stamp
    shutil.copyfile(TARGET, bak)
    out = src.replace(OLD, NEW, 1)
    open(TARGET, "w", encoding="utf-8").write(out)
    try:
        compile(out, TARGET, "exec")
    except SyntaxError as ex:
        shutil.copyfile(bak, TARGET)
        raise SystemExit("REFUSED: compile failed (%s); restored from %s" % (ex, bak))
    print("patched %s (%s); backup %s" % (TARGET, MARK, bak))
    return 0


if __name__ == "__main__":
    sys.exit(main())
